#include <cstdio>
#include <string>
#include <vector>
#include <sstream>
#include <iostream>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<std::string> words;
    std::string w;
    while (iss >> w) words.push_back(w);

    for (int i = (int)words.size() - 1; i >= 0; --i) {
        if (i != (int)words.size() - 1) printf(" ");
        printf("%s", words[i].c_str());
    }
    printf("\n");
    return 0;
}
